import base64
import gzip
import subprocess
from pathlib import Path

PATCH_B64 = """"""

patch_path = Path("/tmp/dev13-source.patch")
patch_path.write_bytes(gzip.decompress(base64.b64decode(PATCH_B64)))
subprocess.run(["git", "apply", "--check", str(patch_path)], check=True)
subprocess.run(["git", "apply", str(patch_path)], check=True)

gradle = Path("gradle.properties")
text = gradle.read_text()
old = "mod_version=0.3.0-phase3-dev12.1"
new = "mod_version=0.3.0-phase3-dev13"
if old not in text:
    raise SystemExit("expected dev12.1 mod_version not found")
gradle.write_text(text.replace(old, new, 1))
